INSERT INTO `BlogPost` (`id`, `publicId`, `authorId`, `title`, `slug`, `excerpt`, `body`, `coverImageUrl`, `coverImageAlt`, `seoTitle`, `seoDescription`, `status`, `publishedAt`, `archivedAt`, `createdAt`, `updatedAt`)
VALUES
  ('blog_seed_home_salon_prep', 'blog_home_salon_prep', NULL, 'How to Prepare for Your Home Salon Appointment', 'prepare-for-home-salon-appointment', 'A little preparation helps your beauty professional begin on time and gives you a calmer, more comfortable salon experience at home.', '## Choose a comfortable space\n\nPick a well-lit area with enough room for the professional to arrange products and move safely. A chair near a power point and easy access to water can be useful for many services.\n\n## Share important details early\n\nMention sensitivities, allergies, recent skin treatments or a special occasion while booking. Clear information helps the professional understand what you need before arriving.\n\n## Keep the area ready\n\nClear a small working surface and keep pets or interruptions away from the service area. Wear comfortable clothing that suits the treatment you selected.\n\n## Allow time after the service\n\nAvoid packing your schedule too tightly. A few unhurried minutes after the appointment gives you time to review after-care advice and enjoy the result.', NULL, NULL, 'Prepare for a Home Salon Appointment', 'Simple steps to prepare your space and yourself for a smooth home salon appointment in Lucknow.', 'PUBLISHED', '2026-09-14 04:30:00.000', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('blog_seed_skincare_routine', 'blog_skincare_routine', NULL, 'A Simple Skincare Routine Between Facial Appointments', 'simple-skincare-routine-between-facials', 'Keep your post-facial glow for longer with a gentle everyday routine focused on cleansing, moisture and sun protection.', '## Start with gentle cleansing\n\nUse a mild cleanser that leaves your skin comfortable instead of tight. Cleansing in the evening helps remove sunscreen, makeup and the day''s buildup.\n\n## Support the skin barrier\n\nApply a moisturiser suited to your skin type while the skin is slightly damp. Introduce active ingredients slowly and avoid combining several strong products at once.\n\n## Make sunscreen a daily habit\n\nUse broad-spectrum sunscreen during the day and reapply when you spend extended time outdoors. Sun protection supports the results of your professional skincare routine.\n\n## Watch how your skin responds\n\nPause any product that causes persistent burning or irritation. For ongoing concerns, seek advice from a qualified dermatologist rather than relying only on beauty treatments.', NULL, NULL, 'Simple Skincare Routine Between Facials', 'A gentle cleansing, moisturising and sun protection routine to follow between facial appointments.', 'PUBLISHED', '2026-09-11 04:30:00.000', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('blog_seed_waxing_guide', 'blog_waxing_guide', NULL, 'Choosing the Right Waxing Service at Home', 'choosing-at-home-waxing-service', 'Understand the main choices before booking an at-home waxing service, from the treatment area to skin preparation and after-care.', '## Start with the treatment area\n\nChoose only the areas you want treated and check the service inclusions before confirming. Packages can be convenient, while individual services offer more flexibility.\n\n## Prepare your skin gently\n\nAvoid aggressive exfoliation immediately before the appointment. Clean, dry skin without heavy oils or lotions makes the service setup easier.\n\n## Discuss sensitivity\n\nTell your professional about sensitive skin, recent peels or products that may affect your skin. If you are unsure whether waxing is appropriate, consult a healthcare professional first.\n\n## Plan simple after-care\n\nWear loose clothing where practical and avoid intense heat, friction or fragranced products on freshly waxed areas for a short period after the service.', NULL, NULL, 'Guide to At-Home Waxing Services', 'What to consider before choosing and preparing for a waxing service at home.', 'PUBLISHED', '2026-09-08 04:30:00.000', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  ('blog_seed_mani_pedi', 'blog_mani_pedi_care', NULL, 'How to Make Your Manicure and Pedicure Last Longer', 'make-manicure-pedicure-last-longer', 'Protect freshly finished hands and feet with practical habits that help your manicure and pedicure stay neat for longer.', '## Give the finish time to settle\n\nBe gentle with your hands and feet immediately after the appointment. Avoid unnecessary pressure, tight footwear or tasks that can mark a fresh finish.\n\n## Moisturise consistently\n\nUse hand cream and foot cream regularly, focusing on dry areas. Cuticle oil can help keep the nail area looking cared for between appointments.\n\n## Protect your hands during chores\n\nWear gloves for cleaning and prolonged contact with water. Household products and repeated soaking can shorten the life of a manicure.\n\n## Maintain, do not pick\n\nUse a nail file gently if an edge catches. Picking at polish or damaged areas can worsen the finish and may affect the natural nail underneath.', NULL, NULL, 'Make a Manicure and Pedicure Last Longer', 'Easy after-care habits to help an at-home manicure and pedicure stay neat for longer.', 'PUBLISHED', '2026-09-05 04:30:00.000', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
